initJs:
function(container, apiUrl, tables) {
  let currentEditingId = null;

  // 重要度レベルのスタイル取得
  function getPriorityStyle(priority) {
    switch(priority) {
      case '高': return 'background: #dc3545; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      case '中': return 'background: #ffc107; color: #000; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      case '低': return 'background: #28a745; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      default: return 'background: var(--border); color: var(--text); padding: 2px 6px; border-radius: 4px; font-size: 11px;';
    }
  }

  // 確認状況のスタイル取得
  function getStatusStyle(status) {
    switch(status) {
      case '未確認': return 'background: #dc3545; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      case '確認済み': return 'background: #ffc107; color: #000; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      case '対応済み': return 'background: #28a745; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      default: return 'background: var(--border); color: var(--text); padding: 2px 6px; border-radius: 4px; font-size: 11px;';
    }
  }

  // 検証結果テーブル再描画
  function renderValidationResults(rows) {
    const tbody = container.querySelector("#validation-results");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}" style="height: 36px;">
        <td style="padding: 6px 10px;">
          <input type="checkbox" class="row-check" data-id="${r.id}" style="accent-color: var(--primary);">
        </td>
        <td style="padding: 6px 10px; font-size: 13px;">${new Date(r.検出日時).toLocaleString() || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${r.作業員名 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${r.異常値種別 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${r.検出項目 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${r.検出値 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${r.閾値 || ""}</td>
        <td style="padding: 6px 10px;">
          <span style="${getPriorityStyle(r.重要度)}">${r.重要度 || ""}</span>
        </td>
        <td style="padding: 6px 10px;">
          <span style="${getStatusStyle(r.確認状況)}">${r.確認状況 || ""}</span>
        </td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary correct-btn" data-id="${r.id}" style="font-size: 11px; padding: 4px 8px; margin-right: 4px;">修正</button>
          <button class="action-btn secondary approve-btn" data-id="${r.id}" style="font-size: 11px; padding: 4px 8px;">承認</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ描画
  renderValidationResults(tables[4]?.records || []);

  // 日付の初期値設定（過去7日間）
  const today = new Date();
  const weekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
  container.querySelector("#input-start-date").value = weekAgo.toISOString().split('T')[0];
  container.querySelector("#input-end-date").value = today.toISOString().split('T')[0];

  // 検証実行ボタン
  container.querySelector("#btn-validate").addEventListener("click", async () => {
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const errorType = container.querySelector("#select-error-type").value;

    if (!startDate || !endDate) {
      alert("検証期間を選択してください");
      return;
    }

    // 進捗表示開始
    const progressArea = container.querySelector("#progress-area");
    const progressBar = container.querySelector("#progress-bar");
    const progressText = container.querySelector("#progress-text");
    const statusText = container.querySelector("#validation-status");

    progressArea.classList.remove("hidden");
    statusText.textContent = "検証中...";

    // 進捗アニメーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 90) progress = 90;
      progressBar.style.width = progress + "%";
      progressText.textContent = Math.round(progress) + "%";
    }, 200);

    try {
      // 異常値検出ログを取得
      const rows = await window.aivicApi.list(4);
      let filteredRows = rows || [];

      // 期間フィルタ
      filteredRows = filteredRows.filter(r => {
        const detectionDate = new Date(r.検出日時).toISOString().split('T')[0];
        return detectionDate >= startDate && detectionDate <= endDate;
      });

      // エラー種別フィルタ
      if (errorType) {
        filteredRows = filteredRows.filter(r => r.異常値種別 === errorType);
      }

      // 進捗完了
      setTimeout(() => {
        clearInterval(progressInterval);
        progressBar.style.width = "100%";
        progressText.textContent = "100%";
        statusText.textContent = "完了";

        renderValidationResults(filteredRows);

        // 完了通知
        const notificationArea = container.querySelector("#notification-area");
        const notificationText = container.querySelector("#notification-text");
        notificationText.textContent = `${filteredRows.length}件の異常値を検出しました。`;
        notificationArea.classList.remove("hidden");

        setTimeout(() => {
          progressArea.classList.add("hidden");
        }, 1000);
      }, 1000);

    } catch (error) {
      clearInterval(progressInterval);
      progressArea.classList.add("hidden");
      alert("検証処理でエラーが発生しました");
    }
  });

  // 全選択チェックボックス
  container.querySelector("#check-all").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".row-check");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateBulkApproveButton();
  });

  // 一括承認チェックボックス
  container.querySelector("#check-bulk-approve").addEventListener("change", updateBulkApproveButton);

  function updateBulkApproveButton() {
    const bulkCheck = container.querySelector("#check-bulk-approve").checked;
    const selectedRows = container.querySelectorAll(".row-check:checked");
    const bulkBtn = container.querySelector("#btn-bulk-approve");
    bulkBtn.disabled = !bulkCheck || selectedRows.length === 0;
  }

  // 行選択時の一括承認ボタン更新
  container.addEventListener("change", (e) => {
    if (e.target.classList.contains("row-check")) {
      updateBulkApproveButton();
    }
  });

  // 一括承認ボタン
  container.querySelector("#btn-bulk-approve").addEventListener("click", async () => {
    const selectedRows = container.querySelectorAll(".row-check:checked");
    if (selectedRows.length === 0) return;

    if (!confirm(`${selectedRows.length}件の異常値を承認しますか？`)) return;

    try {
      for (const checkbox of selectedRows) {
        const id = checkbox.dataset.id;
        await window.aivicApi.update(4, id, { 確認状況: "対応済み", 確認日時: new Date().toISOString() });
      }

      const rows = await window.aivicApi.list(4);
      renderValidationResults(rows || []);

      // 選択解除
      container.querySelector("#check-all").checked = false;
      container.querySelector("#check-bulk-approve").checked = false;
      updateBulkApproveButton();

    } catch (error) {
      alert("一括承認処理でエラーが発生しました");
    }
  });

  // 修正・承認ボタンのイベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 修正ボタン
    const correctBtn = e.target.closest(".correct-btn");
    if (correctBtn) {
      currentEditingId = correctBtn.dataset.id;
      const modal = container.querySelector("#correction-modal");
      modal.classList.remove("hidden");
      return;
    }

    // 承認ボタン
    const approveBtn = e.target.closest(".approve-btn");
    if (approveBtn) {
      if (!confirm("この異常値を承認しますか？")) return;

      try {
        await window.aivicApi.update(4, approveBtn.dataset.id, { 
          確認状況: "対応済み", 
          確認日時: new Date().toISOString() 
        });

        const rows = await window.aivicApi.list(4);
        renderValidationResults(rows || []);
      } catch (error) {
        alert("承認処理でエラーが発生しました");
      }
      return;
    }
  });

  // モーダル閉じる
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#correction-modal").classList.add("hidden");
  });

  container.querySelector("#btn-cancel-correction").addEventListener("click", () => {
    container.querySelector("#correction-modal").classList.add("hidden");
  });

  // 修正保存
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    const startTime = container.querySelector("#modal-start-time").value;
    const endTime = container.querySelector("#modal-end-time").value;
    const reason = container.querySelector("#modal-reason").value;

    if (!startTime || !endTime || !reason) {
      alert("全ての項目を入力してください");
      return;
    }

    try {
      // 異常値ログを対応済みに更新
      await window.aivicApi.update(4, currentEditingId, { 
        確認状況: "対応済み", 
        確認日時: new Date().toISOString(),
        対応メモ: reason
      });

      // 作業記録も更新（実際の修正）
      // ここでは異常値ログの対象レコードIDを使って作業記録を更新
      const logRecord = await window.aivicApi.list(4);
      const targetLog = logRecord.find(r => r.id === currentEditingId);
      if (targetLog && targetLog.検出対象レコードID) {
        const workTime = Math.floor((new Date(endTime) - new Date(startTime)) / (1000 * 60));
        await window.aivicApi.update(1, targetLog.検出対象レコードID, {
          作業開始時刻: startTime,
          作業終了時刻: endTime,
          作業時間: workTime
        });
      }

      const rows = await window.aivicApi.list(4);
      renderValidationResults(rows || []);

      container.querySelector("#correction-modal").classList.add("hidden");

      // フォームリセット
      container.querySelector("#modal-start-time").value = "";
      container.querySelector("#modal-end-time").value = "";
      container.querySelector("#modal-reason").value = "";

    } catch (error) {
      alert("修正保存でエラーが発生しました");
    }
  });

  // 検証ログ出力
  container.querySelector("#btn-export-log").addEventListener("click", async () => {
    try {
      const rows = await window.aivicApi.list(4);
      if (!rows || rows.length === 0) {
        alert("出力するデータがありません");
        return;
      }

      const headers = ["検出日時", "作業員名", "異常値種別", "検出項目", "検出値", "閾値", "重要度", "確認状況", "対応メモ"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...rows.map(r => [
          r.検出日時 || "",
          r.作業員名 || "",
          r.異常値種別 || "",
          r.検出項目 || "",
          r.検出値 || "",
          r.閾値 || "",
          r.重要度 || "",
          r.確認状況 || "",
          r.対応メモ || ""
        ].map(field => `"${String(field).replace(/"/g, '""')}"`).join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `validation_log_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();

    } catch (error) {
      alert("ログ出力でエラーが発生しました");
    }
  });

  // 再検証ボタン
  container.querySelector("#btn-revalidate").addEventListener("click", () => {
    container.querySelector("#btn-validate").click();
  });
}
